"""AI background music for Dub jobs, generated by the local music engine (ACE-Step, MIT).

A thin adapter over ``services.music``: it asks for an instrumental sized to the video and
writes it to the job folder. The music server starts on demand, so there is nothing for the
user to launch; when the engine is not installed the feature reports it and does nothing.
"""
from __future__ import annotations

from typing import AsyncIterator, Optional

from services import music

MAX_TRACK_SECONDS = music.MAX_SECONDS  # longer videos loop the track at export


async def status() -> dict:
    info = music.get_engine().status()
    return {"installed": info["installed"], "running": info["running"], "model_ready": info["installed"]}


async def generate(style: str, duration: float, out_path: str, seed: Optional[int] = None,
                   bpm: Optional[int] = None) -> AsyncIterator[dict]:
    """Generate one instrumental track; yields progress events, writes `out_path`."""
    request = music.MusicRequest(prompt=style, instrumental=True, duration=min(duration, MAX_TRACK_SECONDS),
                                 bpm=bpm, seed=seed)
    async for event in music.get_engine().generate(request, out_path):
        yield event
